ST.xhtml:
// =============================================================================
// 场景：批量给 5 台生产线 PLC 互相加路由，本例演示其中一对的添加。
// 价值：替代手动开 System Manager 操作。
// 验证：改 bAddRoute := TRUE，观察 bBusy 短暂 TRUE 后 bDoneOk → TRUE；nErr 应为 0；上目标机器看路由表新增条目。
// 验证步骤：
//   1. 右键 PLC 项目 → Import PLCopenXML → 选本文件
//   2. 引用 Tc2_Utilities（References → Add library）
//   3. 编译 → 登录 → 运行；按上方『验证』行的指示在线写值观察
// =============================================================================

fbFB_AddRouteEntry(
    sNetID := '',  // 本机做目标
    bExecute := bAddRoute,
    sRemoteNetID := '10.0.0.42.1.1',
    sRemoteIP := '10.0.0.42',
    sRemoteName := 'CX-Line2',
    sRemoteRouteName := 'AutoRoute-Line2',
    sUsername := 'Administrator',
    sPassword := 'GeheimPW',
    eAddRouteOptions := eRemoteRouteStatic_StoreOnRemote,
    tTimeout := DEFAULT_ADS_TIMEOUT,
    bBusy => bBusyFlag,
    bErr => bDoneOk,
    nErrId => nErr
);
bDoneOk := NOT bDoneOk;  // 取反让 TRUE 表示成功
